def int_to_roman(n):
    vals = [(1000, "M"), (500, "D"), (100, "C"), (50, "L"), (10, "X"), (5, "V"), (1, "I")]
    # First, try using only addition logic to get a base result
    out = ""
    for v, s in vals:
        while n >= v:
            n -= v
            out += s

    # Now fix over-subtractions by adding back values that should have been subtracted
    # For each value, if we've over-subtracted (n < 0), we need to add it back
    # But we need to be careful about IV and IX cases

    adjusted = 0
    for v, s in vals:
        # Check if we should have subtracted this value instead of adding it
        if n < 0 and out.startswith(s + "X"):
            # We're trying to add M but we've over-subtracted C (100)
            # Instead of adding M twice, we should add C once
            adjusted -= v * 2  # Subtract the over-subtraction
        elif n < 0 and out.startswith(s + "L"):
            adjusted -= v * 2
        elif n < 0 and out.startswith(s + "X"):
            adjusted -= v * 2
        elif n < 0 and out.startswith(s + "V"):
            adjusted -= v * 2
        else:
            # We should have subtracted, but we're adding it (over-subtracted)
            adjusted += v

    return out + str(adjusted)

# Test cases
